       phone, address, userDesc, userRole, imgPath, status,
       createdBy, creationDate, modifyBy, modifyDate
FROM tb_user
WHERE userCode = #{userCode}
  AND userPassword = #{userPassword}

SELECT id, userCode, userName, userPassword, gender, birthday, email, phone, address, userDesc, userRole, imgPath, status, registerReason, createdBy, creationDate, modifyBy, modifyDate FROM tb_user
AND userName LIKE CONCAT('%', #{userName}, '%')
AND userRole = #{roleId}
ORDER BY creationDate DESC LIMIT #{start}, #{size}

